def _isle(girdi):
    sira, parca = girdi
    x = parca            # float32 dönüşümü kaldırıldı
    if sira == 0:
        x += 50
    elif sira == 1:
        x -= 50
    return np.clip(x, 0, 255).astype(np.uint8)

def _sure_olc(gri, hesapla, tekrar):
    for _ in range(tekrar):
        baslangic = perf_counter()
        sonuc = hesapla(gri)
    return (perf_counter() - baslangic) / tekrar, sonuc
